1	const PROCESSING_FEE = 5;
2	
3	const BASE_PREMIUM_BY_ITEM_TYPE = {
4	  sword: 100,
5	  amulet: 60,
6	  staff: 80,
7	  potion: 40,
8	  rune: 25,
9	  moonstone: 25,
10	} as const satisfies Record<string, number>;
11	
12	type InsurableItemType = keyof typeof BASE_PREMIUM_BY_ITEM_TYPE;
13	
14	const BLOCK_SIZE = 3;
15	
16	const BLOCK_BASE_PREMIUM = 60;
17	
18	const CURSE_SURCHARGE_RATE = 0.5;
19	
20	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
21	
22	export type ScenarioResult = { premium: number };
23	
24	export type ScenarioOutcome = { results: ScenarioResult[] };
25	
26	type Item = { type: InsurableItemType; cursed?: boolean };
27	
28	type Scenario = { steps: { items: Item[] }[] };
29	
30	// Amounts are rounded in the MHPCO's favour: premiums (charged to the
31	// customer) round up.
32	const roundPremiumInMHPCOsFavour = (amount: number): number =>
33	  Math.ceil(amount);
34	
35	const countByItemType = (items: Item[]): Map<InsurableItemType, number> => {
36	  const counts = new Map<InsurableItemType, number>();
37	
38	  for (const item of items) {
39	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
40	  }
41	
42	  return counts;
43	};
44	
45	// Exactly 3 alike components form a building block at a special base premium.
46	const basePremiumForAlikeItems = (
47	  type: InsurableItemType,
48	  count: number,
49	): number =>
50	  count === BLOCK_SIZE
51	    ? BLOCK_BASE_PREMIUM
52	    : count * BASE_PREMIUM_BY_ITEM_TYPE[type];
53	
54	const basePremiumOf = (items: Item[]): number =>
55	  [...countByItemType(items)]
56	    .map(([type, count]) => basePremiumForAlikeItems(type, count))
57	    .reduce((total, premium) => total + premium, 0);
58	
59	// Item-specific modifiers apply to the affected item's own base premium,
60	// not to the policy total.
61	const curseSurchargeOf = (items: Item[]): number =>
62	  items
63	    .filter((item) => item.cursed)
64	    .reduce(
65	      (total, item) =>
66	        total + BASE_PREMIUM_BY_ITEM_TYPE[item.type] * CURSE_SURCHARGE_RATE,
67	      0,
68	    );
69	
70	// Policy-wide modifiers are computed from the policy base premium, so the
71	// first insurance surcharge is 10 % of the base — not of base plus curse.
72	const quotePremium = (items: Item[]): number => {
73	  const basePremium = basePremiumOf(items);
74	
75	  return roundPremiumInMHPCOsFavour(
76	    basePremium +
77	      curseSurchargeOf(items) +
78	      basePremium * FIRST_INSURANCE_SURCHARGE_RATE +
79	      PROCESSING_FEE,
80	  );
81	};
82	
83	export const runScenario = (scenario: unknown): ScenarioOutcome => {
84	  const { steps } = scenario as Scenario;
85	
86	  const results = steps.map((step) => ({ premium: quotePremium(step.items) }));
87	
88	  return { results };
89	};
